cat > /app/start.sh <<'SH'
#!/bin/sh
set -eu
mkdir -p /var/lib/huddle
python3 -c 'import sys;sys.path.insert(0,"/app");import server;server.init()'
pids=""
for n in 0 1 2; do python3 /app/server.py "$n" >/tmp/huddle-$n.log 2>&1 & pids="$pids $!"; done
trap 'kill $pids 2>/dev/null || true' TERM INT EXIT
while :; do
 for n in 0 1 2; do
  if ! kill -0 $(echo $pids | awk "{print \$$((n+1))}") 2>/dev/null; then python3 /app/server.py "$n" >/tmp/huddle-$n.log 2>&1 & pids="$pids $!"; fi
 done
 sleep 1
done
SH
chmod +x /app/start.sh
: > /app/requirements.txt
ls -l /app/server.py /app/start.sh /app/requirements.txt
